import type { LucideIcon } from 'lucide-react'
import {
  BarChart2,
  Briefcase,
  CalendarDays,
  CreditCard,
  FolderKanban,
  Image,
  Inbox,
  LayoutDashboard,
  MapPin,
  MessageSquare,
  Package,
  Megaphone,
  FileText,
  Settings,
  Sparkles,
  Users,
  Zap,
} from 'lucide-react'

export type PresetNavRole = 'owner' | 'admin' | 'artist' | 'receptionist' | 'guest_artist'
/**
 * NavRole includes preset roles and custom roles.
 * Custom roles use the pattern `custom:${string}`.
 * For nav item filtering, resolve custom roles to their cloned_from parent via
 * `resolveNavRole()` in lib/team/permissions.ts before comparing to requiredRoles.
 */
export type NavRole = PresetNavRole | `custom:${string}`
export type PlanTier = 'solo' | 'studio' | 'pro' | 'enterprise'

/**
 * Static badge type displayed on the nav item.
 *  - count: resolved from dynamicBadge at render time (e.g. "4", "1.2k")
 *  - dot: small red circle (inventory alerts, urgent signals)
 *  - new: emerald outline "NEW" label
 */
export type BadgeType = 'count' | 'dot' | 'new'

/**
 * Which real-time count this item's badge should reflect.
 * Resolved server-side in layout.tsx and passed as dynamicBadges prop.
 */
export type DynamicBadgeKey =
  | 'inbox'
  | 'calendar'
  | 'clients'
  | 'messages'
  | 'inventory'
  | 'projects'

export interface NavItem {
  label: string
  href: string
  icon: LucideIcon
  requiredRoles: NavRole[]
  requiredPlan?: PlanTier
  featureKey?: string
  /** Static badge type. For 'count' and 'dot', also set dynamicBadge. */
  badgeType?: BadgeType
  /** Which dynamic count this badge renders. badgeType must also be set. */
  dynamicBadge?: DynamicBadgeKey
  /** If set, this item is hidden when the user lacks this permission key */
  requiredPermission?: string
}

export interface NavGroup {
  /** null = unlabeled group (no SidebarGroupLabel rendered) */
  label: string | null
  items: NavItem[]
  condition?: 'always' | 'multi-location'
}

/**
 * S18 sidebar — 5 groups matching the InkOS v2 artifact spec + S18 additions.
 *
 * Group 1 (unlabeled): Today / Inbox / Calendar / Projects / Messages
 * Group 2 STUDIO:      Clients / Team / Flash & Portfolio / Flash Events
 * Group 3 OPERATIONS:  Payments / Inventory / Forms / Analytics
 * Group 4 GROWTH:      AI / Marketing
 * Group 5 LOCATIONS:   (multi-location only) Locations
 * Footer utility:      Settings
 *
 * S18 adds:
 *  - Projects nav item (multi-session tattoos — biggest moat per
 *    competitor research; TattooGenda is the only rival with this and
 *    their UI is 2015-era)
 *  - Flash Events (one-off themed booking days)
 *  - Locations group (hidden when locationCount <= 1)
 *  - Messages dynamicBadge wired to unread conversations
 *  - DynamicBadgeKey extended with 'projects'
 *
 * Commissions + Payroll consolidated into /payments?tab= (redirects in next.config.ts).
 * Waitlist lives as a tab inside /appointments.
 *
 * Item count by role (owner/pro, single-location, excluding footer Settings):
 *  owner/admin:    15 items
 *  artist:         10 items
 *  receptionist:   11 items
 *  guest_artist:    5 items
 *
 * With multi-location (+1 item for owner/admin): Locations.
 */
export const APP_NAV: NavGroup[] = [
  // ── UNLABELED TOP ─────────────────────────────────────────────────────────
  {
    label: null,
    items: [
      {
        label: 'Dashboard',
        href: '/dashboard',
        icon: LayoutDashboard,
        requiredRoles: ['owner', 'admin', 'artist', 'receptionist', 'guest_artist'],
      },
      {
        label: 'Inbox',
        href: '/inbox',
        icon: Inbox,
        requiredRoles: ['owner', 'admin', 'artist', 'receptionist', 'guest_artist'],
        badgeType: 'count',
        dynamicBadge: 'inbox',
      },
      {
        label: 'Calendar',
        href: '/calendar',
        icon: CalendarDays,
        requiredRoles: ['owner', 'admin', 'artist', 'receptionist', 'guest_artist'],
        badgeType: 'count',
        dynamicBadge: 'calendar',
      },
      {
        // S18: multi-session tattoo workflow primitive (sleeves, back pieces,
        // bodysuits). First-class moat per competitor research. Pro+ gated.
        label: 'Projects',
        href: '/projects',
        icon: FolderKanban,
        requiredRoles: ['owner', 'admin', 'artist', 'receptionist', 'guest_artist'],
        requiredPlan: 'pro',
        featureKey: 'projects',
        badgeType: 'count',
        dynamicBadge: 'projects',
      },
      {
        label: 'Messages',
        href: '/messages',
        icon: MessageSquare,
        requiredRoles: ['owner', 'admin', 'artist', 'receptionist', 'guest_artist'],
        requiredPlan: 'studio',
        featureKey: 'omnichannel_inbox',
        badgeType: 'count',
        dynamicBadge: 'messages',
      },
    ],
  },

  // ── STUDIO ────────────────────────────────────────────────────────────────
  {
    label: 'STUDIO',
    items: [
      {
        label: 'Clients',
        href: '/clients',
        icon: Users,
        requiredRoles: ['owner', 'admin', 'artist', 'receptionist'],
        badgeType: 'count',
        dynamicBadge: 'clients',
      },
      {
        // Tab host: Roster / Schedules / Guest Artists / Permissions
        // Route stays /artists — labelled "Team" per S13/S17
        label: 'Team',
        href: '/artists',
        icon: Briefcase,
        requiredRoles: ['owner', 'admin', 'receptionist'],
      },
      {
        label: 'Flash & Portfolio',
        href: '/portfolio',
        icon: Image,
        requiredRoles: ['owner', 'admin', 'artist'],
      },
      {
        // Flash day events — one-off themed events with pre-set booking slots
        label: 'Flash Events',
        href: '/flash-events',
        icon: Zap,
        requiredRoles: ['owner', 'admin', 'artist', 'receptionist'],
        requiredPlan: 'studio',
        featureKey: 'flash_events',
      },
    ],
  },

  // ── OPERATIONS ────────────────────────────────────────────────────────────
  {
    label: 'OPERATIONS',
    items: [
      {
        // Tab host: Transactions / Commissions / Payroll
        label: 'Payments',
        href: '/payments',
        icon: CreditCard,
        requiredRoles: ['owner', 'admin', 'artist'],
      },
      {
        label: 'Inventory',
        href: '/inventory',
        icon: Package,
        requiredRoles: ['owner', 'admin', 'receptionist'],
        requiredPlan: 'studio',
        featureKey: 'inventory',
        badgeType: 'dot',
        dynamicBadge: 'inventory',
      },
      {
        // Sidebar label "Forms" — route renamed /forms → /forms (S24).
        // The old path still resolves via next.config permanent redirect.
        label: 'Forms',
        href: '/forms',
        icon: FileText,
        requiredRoles: ['owner', 'admin', 'artist', 'receptionist'],
      },
      {
        // Sidebar label "Analytics" — route /reports unchanged
        label: 'Analytics',
        href: '/reports',
        icon: BarChart2,
        requiredRoles: ['owner', 'admin'],
        requiredPlan: 'studio',
        featureKey: 'analytics',
      },
    ],
  },

  // ── GROWTH ────────────────────────────────────────────────────────────────
  {
    label: 'GROWTH',
    items: [
      {
        // Sidebar label "AI" — route /ai-design unchanged
        label: 'AI',
        href: '/ai-design',
        icon: Sparkles,
        requiredRoles: ['owner', 'admin', 'artist'],
        requiredPlan: 'pro',
        featureKey: 'ai_design',
        badgeType: 'new',
      },
      {
        label: 'Marketing',
        href: '/marketing',
        icon: Megaphone,
        requiredRoles: ['owner', 'admin'],
        requiredPlan: 'studio',
        featureKey: 'marketing_basic',
      },
    ],
  },

  // ── LOCATIONS (multi-location only) ───────────────────────────────────────
  // AppSidebar filters out this group when locationCount <= 1.
  {
    label: 'LOCATIONS',
    condition: 'multi-location',
    items: [
      {
        label: 'Locations',
        href: '/locations',
        icon: MapPin,
        requiredRoles: ['owner', 'admin'],
      },
    ],
  },

]

export const APP_SETTINGS_ITEM: NavItem = {
  label: 'Settings',
  href: '/settings',
  icon: Settings,
  requiredRoles: ['owner', 'admin', 'artist', 'receptionist', 'guest_artist'],
}

